/* ==== puchi CRT includes ==== */
/* CRT headers needed by IMPLEMENTATION bodies and by PUCHI_TEST stub TUs
 * (harness clibs has TEST without IMPLEMENTATION). Not part of bare API. */
#include <stdlib.h>
#include <stdarg.h>
#include <float.h>
#include <limits.h>
/* ==== puchi libc defaults (strcasecmp) ==== */
/* Portable strcasecmp / strncasecmp (not ISO C). Emitted under
 * PUCHI_IMPLEMENTATION || PUCHI_TEST (clibs is TEST without IMPL). */
static inline int puchi_strcasecmp(const char *a, const char *b) {
  unsigned char ca, cb;
  for (;;) {
    ca = (unsigned char)PUCHI_TOLOWER((unsigned char)*a++);
    cb = (unsigned char)PUCHI_TOLOWER((unsigned char)*b++);
    if (ca != cb) return (int)ca - (int)cb;
    if (ca == 0) return 0;
  }
}
static inline int puchi_strncasecmp(const char *a, const char *b, size_t n) {
  unsigned char ca, cb;
  if (n == 0) return 0;
  do {
    ca = (unsigned char)PUCHI_TOLOWER((unsigned char)*a++);
    cb = (unsigned char)PUCHI_TOLOWER((unsigned char)*b++);
    if (ca != cb) return (int)ca - (int)cb;
    if (ca == 0) return 0;
  } while (--n != 0);
  return 0;
}
#endif

