sexp_heap sexp_make_heap (const puchi_host *host, size_t size, size_t max_size, size_t chunk_size) {
  sexp_free_list free, next;
  sexp_heap h;
  if (!host || !host->alloc || !host->free) return NULL;
  h =  (sexp_heap) host->alloc(host->userdata, sexp_heap_pad_size(size));
  if (! h) return NULL;
  h->host = *host;
  if (!h->host.diagnose) h->host.diagnose = puchi_default_diagnose;
  if (!h->host.fatal) h->host.fatal = puchi_default_fatal;
  h->modules_set = 0;
  h->static_libraries = NULL;
  h->size = size;
  h->max_size = max_size;
  h->chunk_size = chunk_size;
  h->data = (char*) sexp_heap_align(sizeof(h->data)+(sexp_uint_t)&(h->data));
  free = h->free_list = (sexp_free_list) h->data;
  h->next = NULL;
  next = (sexp_free_list) (((char*)free)+sexp_heap_align(sexp_free_chunk_size));
  free->size = 0; /* actually sexp_heap_align(sexp_free_chunk_size) */
  free->next = next;
  next->size = size - sexp_heap_align(sexp_free_chunk_size);
  next->next = NULL;
  return h;
}

int sexp_grow_heap (sexp ctx, size_t size, size_t chunk_size) {
  size_t cur_size, new_size;
  sexp_heap tmp, h = sexp_heap_last(sexp_context_heap(ctx));
  cur_size = h->size;
  new_size = (size_t) PUCHI_CEIL(SEXP_GROW_HEAP_FACTOR * (double) (sexp_heap_align(((cur_size > size) ? cur_size : size))));
  tmp = sexp_make_heap(&h->host, new_size, h->max_size, chunk_size);
  if (tmp) {
    tmp->next = h->next;
    h->next = tmp;
  }
  return (h->next != NULL);
}

void* sexp_try_alloc (sexp ctx, size_t size) {
  sexp_free_list ls1, ls2, ls3;
  sexp_heap h;
  for (h=sexp_context_heap(ctx); h; h=h->next) {
    for (ls1=h->free_list, ls2=ls1->next; ls2; ls1=ls2, ls2=ls2->next) {
      if (ls2->size >= size) {
        if (ls2->size >= (size + SEXP_MINIMUM_OBJECT_SIZE)) {
          ls3 = (sexp_free_list) (((char*)ls2)+size); /* the tail after ls2 */
          ls3->size = ls2->size - size;
          ls3->next = ls2->next;
          ls1->next = ls3;
        } else {                  /* take the whole chunk */
          ls1->next = ls2->next;
        }
        PUCHI_MEMSET((void*)ls2, 0, size);
        return ls2;
      }
    }
  }
  return NULL;
}


void* sexp_alloc (sexp ctx, size_t size) {
  void *res;
  size_t max_freed, sum_freed, total_size=0;
  sexp_heap h = sexp_context_heap(ctx);
  size = sexp_heap_align(size);
  res = sexp_try_alloc(ctx, size);
  if (! res) {
    max_freed = sexp_unbox_fixnum(sexp_gc(ctx, &sum_freed));
    total_size = sexp_heap_total_size(sexp_context_heap(ctx));
    if (((max_freed < size)
         || ((total_size > sum_freed)
             && (total_size - sum_freed) > (total_size*SEXP_GROW_HEAP_RATIO)))
        && ((!h->max_size) || (total_size < h->max_size)))
      sexp_grow_heap(ctx, size, 0);
    res = sexp_try_alloc(ctx, size);
    if (! res) {
      res = sexp_global(ctx, SEXP_G_OOM_ERROR);
    }
  }
  return res;
}



/* ==== puchi #e mul (F∧¬B; before sexp.c call sites) ==== */
#if !defined(PUCHI_INTEGER_ONLY) && !defined(PUCHI_ENABLE_NUMERICAL_TOWER)
/* Exact #e mantissa * 10^e without sexp_mul (no bignum.c). */
static sexp puchi_fx_or_fl_mul(sexp ctx, sexp a, sexp b) {
  if (sexp_fixnump(a) && sexp_fixnump(b)) {
    sexp_sint_t x = sexp_unbox_fixnum(a), y = sexp_unbox_fixnum(b);
    if (x != 0 && y != 0) {
      if (x > 0) {
        if (y > 0) {
          if (x > SEXP_MAX_FIXNUM / y) goto flo;
        } else {
          if (y < SEXP_MIN_FIXNUM / x) goto flo;
        }
      } else {
        if (y > 0) {
          if (x < SEXP_MIN_FIXNUM / y) goto flo;
        } else {
          if (x == SEXP_MIN_FIXNUM || y == SEXP_MIN_FIXNUM) goto flo;
          if (-x > SEXP_MAX_FIXNUM / -y) goto flo;
        }
      }
    }
    return sexp_fx_mul(a, b);
  flo:
    return sexp_make_flonum(ctx, (double)x * (double)y);
  }
  if (sexp_flonump(a) && sexp_flonump(b))
    return sexp_fp_mul(ctx, a, b);
  if (sexp_flonump(a) && sexp_fixnump(b))
    return sexp_make_flonum(ctx, sexp_flonum_value(a) * (double)sexp_unbox_fixnum(b));
  if (sexp_fixnump(a) && sexp_flonump(b))
    return sexp_make_flonum(ctx, (double)sexp_unbox_fixnum(a) * sexp_flonum_value(b));
  return sexp_type_exception(ctx, NULL, SEXP_NUMBER, sexp_list2(ctx, a, b));
}
#endif

